function configDocCtrl(n,t,i,r){n.configurationDocs=[];n.puntosEmision=[];n.initiload=()=>{showLoader(),t.getEstabAsign().then(t=>{n.establecimientos=t,n.establecimientos.length>0?(n.dataEstab=n.establecimientos.length>0?n.establecimientos[0]:{},n.codEstab=n.dataEstab.codEstab,n.getPuntoEmision(),hideLoader()):(hideLoader(),r.toastr("warning","No tienes asignado ningún Establecimiento"))}).catch(n=>{hideLoader(),console.error(n)})};n.initiload();n.onChangeEstab=()=>{n.dataEstab=n.establecimientos.find(t=>t.codEstab===n.codEstab),n.getPuntoEmision()};n.getPuntoEmision=()=>{t.getDataFormEstabAsig(n.dataEstab).then(t=>{n.puntosEmision=t[0],n.puntosEmision.length>0?(n.idPuntoEmision=n.puntosEmision[0].idPuntoEmision,n.getConfigDocs()):r.toastr("warning","No tienes asignado ningún punto de Emisión")})};n.getConfigDocs=function(){showLoader();i.getData("get","/TipoDocumento/GetConfiguration?idPuntoEmision="+n.idPuntoEmision).then(function(t){hideLoader();t.id==0&&r.toastr("warning",t.message);n.configurationDocs=t.data}).catch(n=>{hideLoader(),console.log(n)})};n.saveConfig=function(t){if(n.idPuntoEmision===undefined||n.idPuntoEmision==null||n.idPuntoEmision==0){r.toastr("warning","Seleccione el punto de emisión");return}if(t.configDoc.ultimaSecuencia===undefined||t.configDoc.ultimaSecuencia==null||t.configDoc.ultimaSecuencia==0){r.toastr("warning","Ingrese el número de secuencia");return}const u={idConfiguracionDocumento:t.configDoc.idConfiguracionDocumento,idPuntoEmision:n.idPuntoEmision,idTipoDocumento:t.configDoc.idTipoDocumento,generacionNro:t.configDoc.generacionNro,ultimaSecuencia:t.configDoc.ultimaSecuencia};showLoader();i.getData("post","/TipoDocumento/SaveConfig",u).then(t=>{if(hideLoader(),t.id==0){r.toastr("warning",t.message);return}t.id==1&&(r.toastr("success",t.message),n.getConfigDocs())}).catch(n=>{hideLoader(),console.log(n)})};n.configDoc=function(){$("#configDocModal").modal("show")}}app.controller("configDocCtrl",configDocCtrl);configDocCtrl.$inject=["$scope","commonService","mainService","toastService"];